//! Detached Attr factories retain genuine owner and document-specific case.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><span id=mount></span><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://attribute-factories.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}


#[test]
fn attribute_name_exact_raw_qualified_identity_html_folding_xml_case_snapshots_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var html=document.implementation.createHTMLDocument('owner'),xml=document.implementation.createDocument(null,'Root'),names=['A\ud800','A\udfff','A\ufffd'],lower=['a\ud800','a\udfff','a\ufffd'];for(var owner of [document,html,xml]){var node=owner.createElement('span'),watch=new MutationObserver(function(){}),attrs=[];watch.observe(node,{attributes:true,attributeOldValue:true});for(var i=0;i<3;i++){var attr=owner.createAttribute(names[i]),actual=owner===xml?names[i]:lower[i];attr.value='value'+i;if(attr.name!==actual||attr.localName!==actual||attr.nodeName!==actual||attr.prefix!==null||attr.namespaceURI!==null)throw 'exact factory name and specified folding';node.setAttributeNode(attr);attrs.push(attr);if(node.getAttribute(names[i])!==attr.value||node.getAttributeNode(names[i])!==attr||node.attributes.getNamedItem(names[i])!==attr)throw 'exact qualified lookup';}var snapshot=node.getAttributeNames(),records=watch.takeRecords();if(snapshot.length!==3||records.length!==3||attrs[0]===attrs[2])throw 'distinct native raw names';for(var i=0;i<3;i++)if(snapshot[i]!==attrs[i].name||records[i].attributeName!==attrs[i].name||records[i].attributeNamespace!==null||records[i].oldValue!==null)throw 'exact names snapshot and original observation';node.setAttribute(names[0],'changed');if(attrs[0].value!=='changed'||attrs[2].value!=='value2')throw 'no replacement-character alias';node.removeAttribute(names[0]);if(attrs[0].ownerElement!==null||attrs[0].value!=='changed'||snapshot[0]!==attrs[0].name||node.getAttributeNode(names[2])!==attrs[2]||node.attributes.length!==2)throw 'real raw removal and immutable snapshot';}
"#);
}
#[test]
fn attribute_name_exact_raw_prefix_local_ns_lookup_clone_replacement_and_observation(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,'Root'),node=xml.documentElement,ns='urn:attribute',prefix='\ud800',local='Lo\udfff',qualified=prefix+':'+local,attr=xml.createAttributeNS(ns,qualified),watch=new MutationObserver(function(){});watch.observe(node,{attributes:true,attributeOldValue:true});attr.value='first';node.setAttributeNodeNS(attr);if(attr.prefix!==prefix||attr.localName!==local||attr.name!==qualified||node.getAttributeNS(ns,local)!=='first'||node.getAttributeNodeNS(ns,local)!==attr||node.attributes.getNamedItemNS(ns,local)!==attr||node.getAttributeNode(qualified)!==attr)throw 'native exact prefix and local';node.setAttributeNS(ns,'\ufffd:'+local,'next');if(attr.name!==qualified||attr.prefix!==prefix||attr.value!=='next'||node.getAttributeNodeNS(ns,'Lo\ufffd')!==null)throw 'prefix preserved and local keys distinct';var copy=node.cloneNode(false),copied=copy.getAttributeNodeNS(ns,local);if(copied===attr||copied.name!==qualified||copied.prefix!==prefix||copied.localName!==local||copied.value!=='next')throw 'clone exact native fields';var next=xml.createAttributeNS(ns,'Q\ud800:'+local);next.value='replacement';if(node.setAttributeNodeNS(next)!==attr||attr.name!==qualified||attr.ownerElement!==null||node.getAttributeNames()[0]!==next.name||node.getAttributeNodeNS(ns,local)!==next)throw 'actual QName replacement and old identity';var records=watch.takeRecords();if(records.length!==3||records[0].attributeName!==local||records[1].oldValue!=='first'||records[2].oldValue!=='next')throw 'exact local mutation record';for(var record of records)if(record.attributeName!==local||record.attributeNamespace!==ns)throw 'exact expanded name observation';node.removeAttributeNS(ns,local);if(next.ownerElement!==null||next.name!=='Q\ud800:'+local||next.ownerDocument!==xml||node.attributes.length)throw 'same raw local removal';
"#);
}
#[test]
fn attribute_name_ordered_conversions_invalid_units_namespace_errors_and_brand_have_no_prefix(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var xml=document.implementation.createDocument(null,'Root'),node=xml.documentElement,order='',caught=false;try{node.setAttributeNS({toString:function(){order+='n';return 'urn:attribute';}},{toString:function(){order+='q';return '\ud800:bad name';}},{toString:function(){order+='v';return 'value';}});}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught||order!=='nqv'||node.attributes.length)throw 'ordered code-unit invalid-name refusal';caught=false;try{xml.createAttribute('\ud800\0');}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught)throw 'NUL remains forbidden';caught=false;try{node.setAttribute('bad \ud800','value');}catch(e){caught=e instanceof DOMException&&e.name==='InvalidCharacterError';}if(!caught||node.attributes.length)throw 'typed ordinary invalid raw name';var prefix='xml\ud800',attr=xml.createAttributeNS('urn:attribute',prefix+':lang');if(attr.prefix!==prefix||attr.localName!=='lang')throw 'raw prefix is not reserved XML spelling';caught=false;try{xml.createAttributeNS(null,'\ud800:Local');}catch(e){caught=e instanceof DOMException&&e.name==='NamespaceError';}if(!caught)throw 'present raw prefix requires namespace';var calls=0;caught=false;try{Document.prototype.createAttributeNS.call({}, {toString:function(){calls++;return 'urn:x';}},{toString:function(){calls++;return '\ud800';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before QName author conversion';
"#);
}
